package com.ruoyi.web.biz;
import java.util.*;
import java.math.BigDecimal;
import java.time.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.AccessDeniedException;
import com.ruoyi.common.utils.SecurityUtils;
import com.ruoyi.common.exception.ServiceException;
@Service
public class DailyReportService {
 final JdbcTemplate db;final EmployeeService users;final TransactionTemplate tx;
 static final ZoneId ZONE=ZoneId.of("Asia/Shanghai");
 public DailyReportService(CompanyOnboardingMapper mapper,EmployeeService users,PlatformTransactionManager tm){db=mapper.database();this.users=users;tx=new TransactionTemplate(tm);}
 LocalDate today(){return LocalDate.now(ZONE);}
 void platform(String p){if(!users.hasPermission("biz:report:"+p)||!users.hasRole(SecurityUtils.getUserId(),"platform_admin")&&SecurityUtils.getUserId()!=1)throw new AccessDeniedException("仅平台管理员可操作");}
 long company(Long requested,String p){if(!users.hasPermission("biz:report:"+p))throw new AccessDeniedException("无填报权限");long user=SecurityUtils.getUserId();boolean platform=user==1||users.hasRole(user,"platform_admin");if(platform){if(requested==null)throw new ServiceException("请选择企业",400);start(requested);return requested;}Long own=users.userCompany(user);if(own==null||requested!=null&&!own.equals(requested))throw new AccessDeniedException("企业归属无效或越权");boolean manager=users.hasRole(user,"company_admin")||users.hasRole(user,"company_business");if(!manager&&!(p.equals("read")&&users.hasRole(user,"company_finance")))throw new AccessDeniedException("当前角色无填报操作权限");return own;}
 public List<Map<String,Object>> companies(){if(SecurityUtils.getUserId()==1||users.hasRole(SecurityUtils.getUserId(),"platform_admin")){if(!users.hasPermission("biz:report:read"))throw new AccessDeniedException("无查询权限");return db.queryForList("SELECT id,company_name FROM biz_company WHERE status='ACTIVE' ORDER BY id");}long c=company(null,"read");return db.queryForList("SELECT id,company_name FROM biz_company WHERE id=?",c);}
 LocalDate start(long c){var rows=db.queryForList("SELECT COALESCE(reporting_start_date,DATE(create_time)) AS day FROM biz_company WHERE id=? AND status='ACTIVE'",c);if(rows.isEmpty())throw new ServiceException("企业无效",400);LocalDate date=((java.sql.Date)rows.get(0).get("day")).toLocalDate();if(date.isBefore(today().minusYears(10)))throw new ServiceException("计报范围超过10年，请先调整开始日期",400);return date;}
 void lockRule(){db.queryForList("SELECT id FROM biz_report_rule WHERE id=1 FOR UPDATE");}
 void lock(long c){db.queryForList("SELECT id FROM biz_company WHERE id=? FOR UPDATE",c);}
 Map<String,Object> rule(){return db.queryForMap("SELECT * FROM biz_report_rule WHERE id=1");}
 boolean flag(Object o){return o instanceof Boolean?(Boolean)o:((Number)o).intValue()!=0;}
 Map<LocalDate,Boolean> calendar(){Map<LocalDate,Boolean> days=new HashMap<>();for(var d:db.queryForList("SELECT * FROM biz_report_calendar"))days.put(((java.sql.Date)d.get("business_date")).toLocalDate(),flag(d.get("required_day")));return days;}
 boolean required(LocalDate day,Map<String,Object> r,Map<LocalDate,Boolean> cal){return cal.containsKey(day)?cal.get(day):!flag(r.get("weekdays_only"))||day.getDayOfWeek().getValue()<6;}
 LocalDate due(Map<String,Object> r){LocalTime cutoff=((java.sql.Time)r.get("cutoff_time")).toLocalTime();return LocalTime.now(ZONE).isBefore(cutoff)?today().minusDays(1):today();}
 Set<LocalDate> submitted(long c,LocalDate from,LocalDate to){Set<LocalDate> dates=new HashSet<>();for(var row:db.queryForList("SELECT output_date FROM biz_daily_output WHERE company_id=? AND output_date BETWEEN ? AND ? AND status IN ('SUBMITTED','CONFIRMED')",c,from,to))dates.add(((java.sql.Date)row.get("output_date")).toLocalDate());return dates;}
 List<LocalDate> missing(long c,Map<String,Object> r,Map<LocalDate,Boolean> cal){LocalDate first=start(c),last=due(r);Set<LocalDate> done=submitted(c,first,last);List<LocalDate> result=new ArrayList<>();for(LocalDate day=first;!day.isAfter(last);day=day.plusDays(1))if(required(day,r,cal)&&!done.contains(day))result.add(day);return result;}
 Map<String,Object> evaluate(long c){return tx.execute(status->{lock(c);var r=rule();var cal=calendar();var missing=missing(c,r,cal);Set<LocalDate> missingSet=new HashSet<>(missing);int streak=0;for(LocalDate day=due(r);!day.isBefore(start(c));day=day.minusDays(1)){if(!required(day,r,cal))continue;if(missingSet.contains(day))streak++;else break;}String state=missing.isEmpty()?"NORMAL":streak>=((Number)r.get("threshold_days")).intValue()?"ALERT":"OVERDUE";
 db.update("INSERT INTO biz_report_compliance(company_id,missing_count,consecutive_days,report_state,last_checked) VALUES(?,?,?,?,CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE missing_count=VALUES(missing_count),consecutive_days=VALUES(consecutive_days),report_state=VALUES(report_state),last_checked=CURRENT_TIMESTAMP",c,missing.size(),streak,state);
 db.update("UPDATE biz_report_reminder SET resolved=1 WHERE company_id=? AND reminder_type='BEFORE_DUE' AND EXISTS(SELECT 1 FROM biz_daily_output d WHERE d.company_id=? AND d.output_date=business_date AND d.status IN ('SUBMITTED','CONFIRMED'))",c,c);
 if(missing.isEmpty())db.update("UPDATE biz_report_reminder SET resolved=1 WHERE company_id=? AND reminder_type<>'BEFORE_DUE'",c);
 else {db.update("INSERT IGNORE INTO biz_report_reminder(company_id,business_date,reminder_type,content) VALUES(?,?,?,?)",c,today(),state,"漏报"+missing.size()+"个应报工作日，连续"+streak+"个应报工作日；当前仅提醒，不限制权限");}
 LocalTime cutoff=((java.sql.Time)r.get("cutoff_time")).toLocalTime(),now=LocalTime.now(ZONE);if(required(today(),r,cal)&&!now.isBefore(cutoff.minusMinutes(((Number)r.get("remind_minutes")).longValue()))&&now.isBefore(cutoff)&&!submitted(c,today(),today()).contains(today()))db.update("INSERT IGNORE INTO biz_report_reminder(company_id,business_date,reminder_type,content) VALUES(?,?,'BEFORE_DUE',?)",c,today(),"今日填报截止时间"+cutoff+"，请及时提交");
 return Map.of("missingDates",missing,"missingCount",missing.size(),"consecutiveDays",streak,"state",state,"mode","REMIND_ONLY","cutoff",cutoff.toString());});}
 public Map<String,Object> compliance(Long c){return evaluate(company(c,"read"));}
 public List<Map<String,Object>> reminders(Long c){return db.queryForList("SELECT * FROM biz_report_reminder WHERE company_id=? ORDER BY id DESC LIMIT 200",company(c,"read"));}
 public int checkAll(){int count=0;for(Long c:db.queryForList("SELECT id FROM biz_company WHERE status='ACTIVE'",Long.class)){try{evaluate(c);count++;}catch(RuntimeException ex){org.slf4j.LoggerFactory.getLogger(getClass()).error("企业{}填报检查失败",c,ex);}}return count;}
 public int runChecks(){platform("config");return checkAll();}
 LocalDate parseDate(String value){try{return LocalDate.parse(value);}catch(Exception ex){throw new ServiceException("日期格式无效",400);}}
 public Map<String,Object> list(Long requested,String from,String to,int page,int size){long c=company(requested,"read");if(page<1||page>100000||size<1||size>100)throw new ServiceException("分页无效",400);String where="company_id=?";List<Object> args=new ArrayList<>();args.add(c);if(from!=null&&!from.isBlank()){where+=" AND output_date>=?";args.add(parseDate(from));}if(to!=null&&!to.isBlank()){where+=" AND output_date<=?";args.add(parseDate(to));}long total=db.queryForObject("SELECT COUNT(*) FROM biz_daily_output WHERE "+where,Long.class,args.toArray());args.add(size);args.add((page-1)*size);return Map.of("rows",db.queryForList("SELECT * FROM biz_daily_output WHERE "+where+" ORDER BY output_date DESC LIMIT ? OFFSET ?",args.toArray()),"total",total);}
 public record Input(Long companyId,LocalDate outputDate,BigDecimal outputValue,String unit,String remark,Integer version){}
 Map<String,Object> record(long c,long id){var rows=db.queryForList("SELECT * FROM biz_daily_output WHERE id=? AND company_id=?",id,c);if(rows.isEmpty())throw new ServiceException("记录不存在或无权访问",404);return rows.get(0);}
 public Map<String,Object> detail(Long requested,long id){return record(company(requested,"read"),id);}
 void open(long c,LocalDate date){if(db.queryForObject("SELECT COUNT(*) FROM biz_report_month WHERE company_id=? AND report_month=? AND status='CONFIRMED'",Long.class,c,YearMonth.from(date).toString())>0)throw new ServiceException("该月已确认，不允许修改或新增",409);}
 @Transactional public long save(Long id,Input in){long c=company(in.companyId(),"write");lock(c);if(in.outputDate()==null||in.outputDate().isAfter(today())||in.outputDate().isBefore(start(c))||in.outputValue()==null||in.outputValue().signum()<0||in.outputValue().scale()>2||in.outputValue().compareTo(new BigDecimal("9999999999999999.99"))>0||!"元".equals(in.unit())||in.remark()!=null&&in.remark().length()>500)throw new ServiceException("日期、金额、单位或备注无效；仅支持元",400);open(c,in.outputDate());if(id==null){if(db.queryForObject("SELECT COUNT(*) FROM biz_daily_output WHERE company_id=? AND output_date=?",Long.class,c,in.outputDate())>0)throw new ServiceException("业务日期已填报，请修改原草稿",409);db.update("INSERT INTO biz_daily_output(company_id,output_date,output_value,unit,remark,status,create_by) VALUES(?,?,?,?,?,'DRAFT',?)",c,in.outputDate(),in.outputValue(),in.unit(),in.remark()==null?"":in.remark(),SecurityUtils.getUsername());return db.queryForObject("SELECT id FROM biz_daily_output WHERE company_id=? AND output_date=?",Long.class,c,in.outputDate());}
 var old=record(c,id);if(!((java.sql.Date)old.get("output_date")).toLocalDate().equals(in.outputDate()))throw new ServiceException("不可转移业务日期",400);if(in.version()==null||db.update("UPDATE biz_daily_output SET output_value=?,remark=?,unit='元',version=version+1,update_by=? WHERE id=? AND company_id=? AND version=? AND status IN ('DRAFT','RETURNED')",in.outputValue(),in.remark()==null?"":in.remark(),SecurityUtils.getUsername(),id,c,in.version())!=1)throw new ServiceException("状态或版本已变化",409);return id;}
 @Transactional public void submit(Long requested,long id,Integer version){long c=company(requested,"write");lock(c);var row=record(c,id);LocalDate date=((java.sql.Date)row.get("output_date")).toLocalDate();if(date.isAfter(today())||date.isBefore(start(c))||!"元".equals(row.get("unit")))throw new ServiceException("日期或金额单位无效",400);open(c,date);if(version==null||db.update("UPDATE biz_daily_output SET status='SUBMITTED',version=version+1,update_by=? WHERE id=? AND company_id=? AND version=? AND status IN ('DRAFT','RETURNED')",SecurityUtils.getUsername(),id,c,version)!=1)throw new ServiceException("状态或版本已变化",409);evaluate(c);}
 YearMonth month(String value){try{return YearMonth.parse(value);}catch(Exception ex){throw new ServiceException("月份无效",400);}}
 Map<String,Object> monthData(long c,YearMonth m){var rows=db.queryForList("SELECT * FROM biz_daily_output WHERE company_id=? AND output_date BETWEEN ? AND ? ORDER BY output_date",c,m.atDay(1),m.atEndOfMonth());BigDecimal total=BigDecimal.ZERO;int count=0,drafts=0;for(var row:rows){if(!"元".equals(row.get("unit")))throw new ServiceException("该月含非元记录，请先核对单位",409);if(Set.of("SUBMITTED","CONFIRMED").contains(row.get("status"))){total=total.add((BigDecimal)row.get("output_value"));count++;}else drafts++;}var r=rule();var cal=calendar();var done=submitted(c,m.atDay(1),m.atEndOfMonth());List<LocalDate> missing=new ArrayList<>();LocalDate last=m.atEndOfMonth().isBefore(due(r))?m.atEndOfMonth():due(r);for(LocalDate d=m.atDay(1).isBefore(start(c))?start(c):m.atDay(1);!d.isAfter(last);d=d.plusDays(1))if(required(d,r,cal)&&!done.contains(d))missing.add(d);var sheets=db.queryForList("SELECT * FROM biz_report_month WHERE company_id=? AND report_month=?",c,m.toString());return Map.of("rows",rows,"totalValue",total,"submittedCount",count,"draftCount",drafts,"missingDates",missing,"status",sheets.isEmpty()?"OPEN":sheets.get(0).get("status"),"version",sheets.isEmpty()?0:sheets.get(0).get("version"),"audits",db.queryForList("SELECT * FROM biz_report_month_audit WHERE company_id=? AND report_month=? ORDER BY id DESC",c,m.toString()));}
 public Map<String,Object> summary(Long requested,String value){return monthData(company(requested,"read"),month(value));}
 @Transactional public void review(Long requested,String value,boolean confirm,Integer version,String opinion){platform("review");lockRule();long c=company(requested,"read");lock(c);YearMonth m=month(value);if(!m.isBefore(YearMonth.from(today()))||m.atEndOfMonth().isBefore(start(c)))throw new ServiceException("只能核对计报范围内的已结束月份",400);if(opinion==null||opinion.isBlank()||opinion.length()>500)throw new ServiceException("核对意见必填",400);var summary=monthData(c,m);if("CONFIRMED".equals(summary.get("status"))||version==null||version.intValue()!=((Number)summary.get("version")).intValue())throw new ServiceException("状态或版本已变化",409);if(confirm&&(!((List<?>)summary.get("missingDates")).isEmpty()||((Number)summary.get("draftCount")).intValue()>0))throw new ServiceException("请先补齐漏报并提交全部草稿",409);
 String state=confirm?"CONFIRMED":"RETURNED";db.update("INSERT INTO biz_report_month(company_id,report_month,status,version) VALUES(?,?,?,1) ON DUPLICATE KEY UPDATE status=VALUES(status),version=version+1",c,m.toString(),state);db.update("UPDATE biz_daily_output SET status=?,version=version+1,update_by=? WHERE company_id=? AND output_date BETWEEN ? AND ? AND status='SUBMITTED'",state,SecurityUtils.getUsername(),c,m.atDay(1),m.atEndOfMonth());db.update("INSERT INTO biz_report_month_audit(company_id,report_month,action,record_count,total_value,opinion,reviewer_id) VALUES(?,?,?,?,?,?,?)",c,m.toString(),state,summary.get("submittedCount"),summary.get("totalValue"),opinion,SecurityUtils.getUserId());evaluate(c);}
 public Map<String,Object> configuration(){platform("config");return Map.of("rule",rule(),"calendar",db.queryForList("SELECT * FROM biz_report_calendar ORDER BY business_date DESC LIMIT 1000"));}
 public record RuleInput(LocalTime cutoff,int remindMinutes,int thresholdDays,boolean weekdaysOnly,Integer version){}
 @Transactional public void configure(RuleInput in){platform("config");lockRule();if(in.cutoff()==null||in.remindMinutes()<0||in.remindMinutes()>240||in.thresholdDays()<1||in.thresholdDays()>366||in.version()==null)throw new ServiceException("规则参数无效",400);if(flag(rule().get("weekdays_only"))!=in.weekdaysOnly()&&db.queryForObject("SELECT COUNT(*) FROM biz_report_month WHERE status='CONFIRMED'",Long.class)>0)throw new ServiceException("已有已确认月份，不能变更工作日计算方式",409);if(db.update("UPDATE biz_report_rule SET cutoff_time=?,remind_minutes=?,threshold_days=?,weekdays_only=?,version=version+1 WHERE id=1 AND version=?",in.cutoff(),in.remindMinutes(),in.thresholdDays(),in.weekdaysOnly(),in.version())!=1)throw new ServiceException("规则版本已变化",409);}
 @Transactional public void calendar(LocalDate date,boolean required,String remark){platform("config");lockRule();if(date==null||date.isBefore(today().minusYears(10))||date.isAfter(today().plusYears(5))||remark==null||remark.isBlank()||remark.length()>200)throw new ServiceException("日期或说明无效",400);if(db.queryForObject("SELECT COUNT(*) FROM biz_report_month WHERE report_month=? AND status='CONFIRMED'",Long.class,YearMonth.from(date).toString())>0)throw new ServiceException("该月已核对，不允许变更计报日历",409);db.update("INSERT INTO biz_report_calendar(business_date,required_day,remark,update_by) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE required_day=VALUES(required_day),remark=VALUES(remark),update_by=VALUES(update_by)",date,required,remark,SecurityUtils.getUsername());}
 @Transactional public void startDate(Long requested,LocalDate date){platform("config");long c=company(requested,"read");lock(c);if(date==null||date.isAfter(today())||date.isBefore(today().minusYears(10)))throw new ServiceException("计报开始日期无效",400);if(db.queryForObject("SELECT COUNT(*) FROM biz_report_month WHERE company_id=? AND status='CONFIRMED'",Long.class,c)>0)throw new ServiceException("已有已确认月份，不允许变更计报起点",409);db.update("UPDATE biz_company SET reporting_start_date=? WHERE id=?",date,c);evaluate(c);}
}
